function ajax_pecas(a,e,c){$.ajax({type:"POST",url:"inc/ajax_pecas.php",data:"flag=H&tipo_id="+a+"&limit="+e+"&search="+c,dataType:"json",success:function(e){if(e&&e.ok)$("#html_pecas_"+a).html(e.data?e.data.html:"");else{var c=e&&e.message?e.message:"Erro ao carregar pecas.";alert("Erro: "+c+". (Copie esse erro e informe ao administrador)")}}})}function ajax_pecas_search(a){ajax_pecas(a,0,$("#search_"+a).val())}$(function(){$("#accordion").accordion({autoHeight:!1,navigation:!0,header:"> div > h3"})});
